// ---- typed client ----

type In<S extends z.ZodType> = z.input<S>;
const enc = encodeURIComponent;

/** The provider's team routes. Team services: `teamServicesApi(api, teamId)`. */
export function teamsApi(api: Client) {
  const one = (id: string) => `/v1/provider/teams/${enc(id)}`;
  return {
    mine: (): Promise<ApiResult<MyTeams>> => api.get("/v1/provider/teams", { schema: myTeamsSchema }),
    create: (body: In<typeof createTeamBodySchema>): Promise<ApiResult<Team>> => api.post("/v1/provider/teams", body, { schema: teamSchema }),
    get: (id: string): Promise<ApiResult<Team>> => api.get(one(id), { schema: teamSchema }),
    update: (id: string, body: In<typeof patchTeamBodySchema>): Promise<ApiResult<Team>> => api.patch(one(id), body, { schema: teamSchema }),
    /** closes the team (lead): the team page goes away and nobody can book it */
    close: (id: string): Promise<ApiResult<undefined>> => api.delete(one(id), { schema: z.undefined() }),
    /** 422 with `missing[]` when it is not ready */
    submit: (id: string, version?: number): Promise<ApiResult<Team>> => api.post(`${one(id)}/submit`, version ? { version } : {}, { schema: teamSchema }),
    leave: (id: string): Promise<ApiResult<MyTeams>> => api.post(`${one(id)}/leave`, {}, { schema: myTeamsSchema }),
    invite: (id: string, body: In<typeof inviteBodySchema>): Promise<ApiResult<Team>> => api.post(`${one(id)}/members`, body, { schema: teamSchema }),
    updateMember: (id: string, providerId: string, body: In<typeof patchMemberBodySchema>): Promise<ApiResult<Team>> => api.patch(`${one(id)}/members/${enc(providerId)}`, body, { schema: teamSchema }),
    removeMember: (id: string, providerId: string): Promise<ApiResult<Team>> => api.delete(`${one(id)}/members/${enc(providerId)}`, { schema: teamSchema }),
    acceptInvite: (teamId: string): Promise<ApiResult<MyTeams>> => api.post(`/v1/provider/team-invites/${enc(teamId)}/accept`, {}, { schema: myTeamsSchema }),
    declineInvite: (teamId: string): Promise<ApiResult<MyTeams>> => api.post(`/v1/provider/team-invites/${enc(teamId)}/decline`, {}, { schema: myTeamsSchema }),
  };
}

/**
 * A team's services (lead): `servicesApi` on `/v1/provider/teams/{teamId}/services` (its answers parse as the plain
 * service; use `getTeamService` for `members[]`), plus who delivers each one.
 */
export function teamServicesApi(api: Client, teamId: string) {
  const base = `/v1/provider/teams/${enc(teamId)}/services`;
  return {
    ...servicesApi(api, base),
    getTeamService: (id: string): Promise<ApiResult<TeamService>> => api.get(`${base}/${enc(id)}`, { schema: teamServiceSchema }),
    listTeamServices: (): Promise<ApiResult<TeamServiceList>> => api.get(base, { schema: teamServiceListSchema }),
    setMembers: (id: string, body: In<typeof putServiceMembersBodySchema>): Promise<ApiResult<TeamService>> => api.put(`${base}/${enc(id)}/members`, body, { schema: teamServiceSchema }),
  };
}
